// Validate a candidate g-extra cut generated by the full radius-one Star.
//
// This proves only an upper bound: if the post-deletion component test passes,
// it establishes kappa_g(A(n,k)) <= |N(S)|. It does not prove optimality.
// Usage: validate_extra_cut [n k] [--dump PATH]
// A .json dump is strict JSON; .md/.markdown and other suffixes are Markdown.

#include <algorithm>
#include <fstream>
#include <iostream>
#include <numeric>
#include <queue>
#include <string>
#include <vector>

struct ArrangementGraph {
    int n;
    int k;
    std::vector<int> status; // -1 invalid, 0 surviving, 1 S, 2 N(S), 3 visited
    std::vector<std::vector<int>> valid_vertices;
    std::vector<int> flat_index;

    ArrangementGraph(int n_value, int k_value) : n(n_value), k(k_value) {
        int capacity = 1;
        for (int i = 0; i < k; ++i)
            capacity *= n;
        status.assign(capacity, -1);
        flat_index.assign(capacity, -1);

        std::vector<int> prefix;
        std::vector<bool> used(n, false);
        generate_valid(prefix, used);
    }

    int encode(const std::vector<int> &vertex) const {
        return std::accumulate(vertex.begin(), vertex.end(), 0,
                               [this](const int code, const int symbol) {
                                   return code * n + symbol;
                               });
    }

    void generate_valid(std::vector<int> &prefix, std::vector<bool> &used) {
        if (static_cast<int>(prefix.size()) == k) {
            const int code = encode(prefix);
            status[code] = 0;
            flat_index[code] = static_cast<int>(valid_vertices.size());
            valid_vertices.push_back(prefix);
            return;
        }
        for (int symbol = 0; symbol < n; ++symbol) {
            if (used[symbol])
                continue;
            used[symbol] = true;
            prefix.push_back(symbol);
            generate_valid(prefix, used);
            prefix.pop_back();
            used[symbol] = false;
        }
    }

    std::vector<int> encoded_neighbors(const std::vector<int> &vertex) const {
        std::vector<int> result;
        std::vector<bool> used(n, false);
        for (const int symbol : vertex)
            used[symbol] = true;

        result.reserve(k * (n - k));
        for (int position = 0; position < k; ++position) {
            for (int symbol = 0; symbol < n; ++symbol) {
                if (used[symbol])
                    continue;
                std::vector<int> neighbor = vertex;
                neighbor[position] = symbol;
                result.push_back(encode(neighbor));
            }
        }
        return result;
    }
};

bool connected(const ArrangementGraph &graph,
               const std::vector<std::vector<int>> &subset) {
    if (subset.empty())
        return true;

    std::vector<bool> visited(subset.size(), false);
    std::queue<int> pending;
    pending.push(0);
    visited[0] = true;
    int reached = 1;

    while (!pending.empty()) {
        const int index = pending.front();
        pending.pop();
        const std::vector<int> neighbors =
            graph.encoded_neighbors(subset[index]);
        for (size_t candidate = 0; candidate < subset.size(); ++candidate) {
            if (visited[candidate])
                continue;
            const int code = graph.encode(subset[candidate]);
            if (std::find(neighbors.begin(), neighbors.end(), code) ==
                neighbors.end())
                continue;
            visited[candidate] = true;
            pending.push(static_cast<int>(candidate));
            ++reached;
        }
    }
    return reached == static_cast<int>(subset.size());
}

void print_vertex(std::ostream &out, const std::vector<int> &vertex) {
    out << '(';
    for (size_t i = 0; i < vertex.size(); ++i) {
        if (i != 0)
            out << ',';
        out << vertex[i];
    }
    out << ')';
}

void print_json_array(std::ostream &out, const std::vector<int> &values) {
    out << '[';
    for (size_t i = 0; i < values.size(); ++i) {
        if (i != 0)
            out << ',';
        out << values[i];
    }
    out << ']';
}

class TeeBuffer : public std::streambuf {
  public:
    TeeBuffer(std::streambuf *first, std::streambuf *second)
        : first_(first), second_(second) {}

  protected:
    int_type overflow(const int_type character) override {
        if (traits_type::eq_int_type(character, traits_type::eof()))
            return traits_type::not_eof(character);
        if (traits_type::eq_int_type(first_->sputc(character),
                                     traits_type::eof()) ||
            traits_type::eq_int_type(second_->sputc(character),
                                     traits_type::eof()))
            return traits_type::eof();
        return character;
    }

    int sync() override {
        return first_->pubsync() == 0 && second_->pubsync() == 0 ? 0 : -1;
    }

  private:
    std::streambuf *first_;
    std::streambuf *second_;
};

class OutputMirror {
  public:
    explicit OutputMirror(const std::string &path)
        : original_(std::cout.rdbuf()), file_(), tee_(nullptr, nullptr),
          active_(!path.empty()) {
        if (!active_)
            return;
        file_.open(path);
        if (!file_)
            return;
        tee_ = TeeBuffer(original_, file_.rdbuf());
        std::cout.rdbuf(&tee_);
    }

    ~OutputMirror() {
        if (active_ && file_.is_open())
            std::cout.rdbuf(original_);
    }

    bool good() const { return !active_ || file_.good(); }

  private:
    std::streambuf *original_;
    std::ofstream file_;
    TeeBuffer tee_;
    bool active_;
};

void dump_markdown(std::ostream &out, const ArrangementGraph &graph,
                   const std::vector<std::vector<int>> &star,
                   const std::vector<int> &boundary_codes,
                   const std::vector<int> &component_sizes, int g, bool valid) {
    const int m = graph.n - graph.k;
    const int degree = graph.k * m;
    const int family_a = graph.k * (graph.k - 1) * m;
    const int family_b = graph.k * (graph.k - 1) / 2 * m * (m - 1);
    const int internal_edges = graph.k * (m + 1) * m / 2;

    out << "# Full radius-one Star cut certificate\n\n";
    out << "## Run summary\n\n"
           "```text\n"
        << "Building A(" << graph.n << ',' << graph.k << ")...\n"
        << "Total valid vertices: " << graph.valid_vertices.size() << "\n\n"
        << "Candidate g = " << g << "\n"
        << "|S| = " << star.size() << "\n"
           "Subset S connectivity verified.\n"
        << "|N(S)| = " << boundary_codes.size() << "\n"
        << "Validating " << g << "-extra cut properties...\n"
           "component sizes after deletion:\n";
    for (const int size : component_sizes)
        out << "  " << size << '\n';
    out << "valid " << g << "-extra cut: " << (valid ? "yes" : "no")
        << "\n";
    if (valid)
        out << "therefore kappa_" << g << "(A(" << graph.n << ',' << graph.k
            << ")) <= " << boundary_codes.size() << "\n";
    out << "```\n\n";
    out << "## Validation\n\n";
    out << "- Graph: `A(" << graph.n << "," << graph.k << ")`\n";
    out << "- Total vertices: `" << graph.valid_vertices.size() << "`\n";
    out << "- Regular degree: `" << degree << "`\n";
    out << "- Candidate: `g = " << g << "`, `|S| = " << star.size() << "`\n";
    out << "- Boundary: `|N(S)| = " << boundary_codes.size() << "`\n";
    out << "- Star connectivity: verified\n";
    out << "- Component sizes after deletion:";
    for (const int size : component_sizes)
        out << " `" << size << "`";
    out << "\n- Valid extra cut: **" << (valid ? "yes" : "no") << "**\n";
    if (valid)
        out << "- Upper bound: `kappa_" << g << "(A(" << graph.n << ','
            << graph.k << ")) <= " << boundary_codes.size() << "`\n";
    out << "\n| graph | degree | g | volume | boundary |\n"
           "|:------|------:|--:|-------:|---------:|\n";
    out << "| A(" << graph.n << ',' << graph.k << ") | " << degree << " | " << g
        << " | " << star.size() << " | " << boundary_codes.size() << " |\n\n";
    out << "Center: `";
    print_vertex(out, star.front());
    out << "`; spare symbols: `{" << graph.k << ",...," << graph.n - 1
        << "}`.\n\n";
    out << "## Star\n\n";
    out << "Each branch mutates exactly one coordinate to one spare "
           "symbol.\n\n";
    out << "| positions | mutation | count |\n"
           "|:----------|:---------|------:|\n";
    out << "| `i = 0..k-1` | `c[i <- s]`, `s` spare | " << graph.k * m
        << " |\n\n";
    out << "The center is adjacent to every leaf. A leaf `c[i <- s]` is\n"
           "adjacent to the center and to the other leaves `c[i <- t]` in its\n"
           "branch.\n\n";
    out << "Star internal edges: " << internal_edges << ". Degree sequence: "
        << "center " << graph.k * m << ", leaves " << m << " repeated "
        << graph.k * m << ".\n\n";
    out << "## Cut `N(S)`\n\n";
    out << "| family | mutation pattern | multiplicity | count |\n"
           "|:-------|:-----------------|-------------:|------:|\n";
    out << "| A | `c[i <- s, j <- i]`, `i != j` | 1 | " << family_a << " |\n";
    out << "| B | `c[i <- s, j <- t]`, `i < j`, `s != t` | 2 | " << family_b
        << " |\n\n";
    out << "Cut size: `" << family_a << " + " << family_b << " = "
        << family_a + family_b << "` (enumerated `" << boundary_codes.size()
        << "`).\n"
           "Cut incidence: family A contributes one incidence per vertex;\n"
           "family B contributes two.\n\n";
}

void dump_json(std::ostream &out, const ArrangementGraph &graph,
               const std::vector<std::vector<int>> &star,
               const std::vector<int> &boundary_codes,
               const std::vector<int> &component_sizes, int g, bool valid) {
    const int m = graph.n - graph.k;
    const int degree = graph.k * m;
    const int family_a = graph.k * (graph.k - 1) * m;
    const int family_b = graph.k * (graph.k - 1) / 2 * m * (m - 1);
    out << "{\n  \"graph\": {\"n\": " << graph.n << ", \"k\": " << graph.k
        << ", \"m\": " << m << ", \"degree\": " << degree
        << "},\n  \"cut_properties\": {\"g\": " << g
        << ", \"target_volume\": " << star.size()
        << ", \"actual_boundary\": " << boundary_codes.size()
        << ", \"valid\": " << (valid ? "true" : "false") << "},\n";
    out << "  \"center_vertex\": ";
    print_json_array(out, star.front());
    out << ",\n  \"spare_symbols\": [";
    for (int symbol = graph.k; symbol < graph.n; ++symbol) {
        if (symbol != graph.k)
            out << ',';
        out << symbol;
    }
    out << "],\n  \"star\": {\"size\": " << star.size()
        << ", \"rule\": \"one coordinate replaced by one spare symbol\","
        << " \"internal_edges\": " << graph.k * (m + 1) * m / 2
        << ", \"degree_sequence\": {\"center\": " << degree
        << ", \"leaves\": " << m << ", \"leaf_count\": " << graph.k * m
        << "}},\n";
    out << "  \"cut\": {\"size\": " << boundary_codes.size()
        << ", \"families\": [\n"
        << "    {\"type\": \"internal_shift\", \"pattern\": "
           "\"c[i<-s,j<-i]\", \"count\": "
        << family_a << ", \"multiplicity\": 1},\n"
        << "    {\"type\": \"double_spare\", \"pattern\": "
           "\"c[i<-s,j<-t]\", \"count\": "
        << family_b << ", \"multiplicity\": 2}\n  ]},\n";
    out << "  \"component_sizes\": [";
    for (size_t i = 0; i < component_sizes.size(); ++i) {
        if (i != 0)
            out << ',';
        out << component_sizes[i];
    }
    out << "]\n}\n";
}

int main(int argc, char **argv) {
    int n = 11;
    int k = 6;
    std::string dump_path;
    int positional = 0;
    for (int arg = 1; arg < argc; ++arg) {
        const std::string value = argv[arg];
        if (value == "-h" || value == "--help") {
            std::cout << "Usage: " << argv[0] << " [n k] [--dump PATH]\n";
            return 0;
        }
        if (value == "--dump") {
            if (arg + 1 >= argc) {
                std::cerr << "Error: --dump requires a path.\n";
                return 1;
            }
            dump_path = argv[++arg];
            continue;
        }
        if (value.rfind("--", 0) == 0) {
            std::cerr << "Error: unknown option '" << value << "'.\n";
            return 1;
        }
        if (positional == 0)
            n = std::stoi(value);
        else if (positional == 1)
            k = std::stoi(value);
        else {
            std::cerr << "Usage: " << argv[0] << " [n k] [--dump PATH]\n";
            return 1;
        }
        ++positional;
    }
    if (n <= k || k < 1) {
        std::cerr << "Error: require n > k >= 1.\n";
        return 1;
    }
    OutputMirror output_mirror(dump_path);
    if (!output_mirror.good()) {
        std::cerr << "Error: cannot open dump file '" << dump_path << "'.\n";
        return 1;
    }
    const bool json_format = dump_path.size() >= 5 &&
                             dump_path.substr(dump_path.size() - 5) == ".json";
    const bool certificate_format = !dump_path.empty();
    const bool show_progress = !certificate_format;

    if (show_progress)
        std::cout << "Building A(" << n << ',' << k << ")...\n";
    ArrangementGraph graph(n, k);
    if (show_progress)
        std::cout << "Total valid vertices: " << graph.valid_vertices.size()
                  << "\n";

    std::vector<int> center(k);
    std::iota(center.begin(), center.end(), 0);
    std::vector<std::vector<int>> star{center};
    graph.status[graph.encode(center)] = 1;
    for (int position = 0; position < k; ++position) {
        for (int symbol = k; symbol < n; ++symbol) {
            std::vector<int> leaf = center;
            leaf[position] = symbol;
            star.push_back(leaf);
            graph.status[graph.encode(leaf)] = 1;
        }
    }

    const int g = static_cast<int>(star.size()) - 1;
    if (show_progress) {
        std::cout << "\nCandidate g = " << g << "\n";
        std::cout << "|S| = " << star.size() << "\n";
    }
    if (!connected(graph, star)) {
        std::cerr << "Error: constructed Star is not connected.\n";
        return 1;
    }
    if (show_progress)
        std::cout << "Subset S connectivity verified.\n";

    int boundary_count = 0;
    std::vector<int> boundary_codes;
    for (const auto &vertex : star) {
        for (const int neighbor : graph.encoded_neighbors(vertex)) {
            if (graph.status[neighbor] != 0)
                continue;
            graph.status[neighbor] = 2;
            boundary_codes.push_back(neighbor);
            ++boundary_count;
        }
    }
    if (show_progress)
        std::cout << "|N(S)| = " << boundary_count << "\n";
    if (n == 11 && k == 6 && boundary_count != 450) {
        std::cerr << "Error: expected |N(S)| = 450 for A(11,6), got "
                  << boundary_count << ".\n";
        return 1;
    }

    if (show_progress)
        std::cout << "Validating " << g << "-extra cut properties...\n";
    std::vector<int> component_sizes;
    for (const auto &vertex : graph.valid_vertices) {
        const int start = graph.encode(vertex);
        if (graph.status[start] != 0 && graph.status[start] != 1)
            continue;

        int size = 0;
        std::queue<int> pending;
        pending.push(start);
        graph.status[start] = 3;
        while (!pending.empty()) {
            const int current = pending.front();
            pending.pop();
            ++size;
            const auto &current_vertex =
                graph.valid_vertices[graph.flat_index[current]];
            for (const int neighbor : graph.encoded_neighbors(current_vertex)) {
                if (graph.status[neighbor] != 0 && graph.status[neighbor] != 1)
                    continue;
                graph.status[neighbor] = 3;
                pending.push(neighbor);
            }
        }
        component_sizes.push_back(size);
    }

    std::sort(component_sizes.begin(), component_sizes.end());
    if (show_progress)
        std::cout << "component sizes after deletion:\n";
    bool valid = component_sizes.size() >= 2;
    for (const int size : component_sizes) {
        if (show_progress)
            std::cout << "  " << size << '\n';
        if (size <= g)
            valid = false;
    }

    if (!valid) {
        if (json_format) {
            dump_json(std::cout, graph, star, boundary_codes, component_sizes,
                      g, false);
        } else if (certificate_format) {
            dump_markdown(std::cout, graph, star, boundary_codes,
                          component_sizes, g, false);
        } else {
            std::cout << "valid " << g << "-extra cut: no\n";
        }
        return 0;
    }
    if (json_format) {
        dump_json(std::cout, graph, star, boundary_codes, component_sizes, g,
                  true);
    } else if (certificate_format) {
        dump_markdown(std::cout, graph, star, boundary_codes, component_sizes,
                      g, true);
    } else {
        std::cout << "valid " << g << "-extra cut: yes\n";
        std::cout << "therefore kappa_" << g << "(A(" << n << ',' << k
                  << ")) <= " << boundary_count << "\n";
    }
    return 0;
}
